pub fn init(sequence_start: usize, sequence_end: usize, next_index: usize) ConcurrentGroup {
            return ConcurrentGroup{ .sequence_start = sequence_start, .sequence_end = sequence_end, .executing = false, .remaining_incomplete_entries = (sequence_end - sequence_start), .failure_skip_to = next_index, .next_sequence_index = 0 };
    }

pub fn tryExtend(self: *ConcurrentGroup, next_sequence_start: usize, next_sequence_end: usize) bool {
            if ((self.sequence_end != next_sequence_start)) {
                return false;
            }
            self.sequence_end = next_sequence_end;
            self.remaining_incomplete_entries = (self.sequence_end - self.sequence_start);
            return true;
    }

pub fn sequences(self: ConcurrentGroup, exec: *Execution) []ExecutionSequence {
            return exec.@"#sequences"[self.sequence_start..self.sequence_end];
    }
};

