pub const Execution = @This();

groups: []ConcurrentGroup = &.{},
@"#sequences": []ExecutionSequence = &.{},
group_index: usize = 0,

pub fn deinit(self: *Execution) void {
        _ = self.bunTest().gpa.free(self.groups);
        _ = self.bunTest().gpa.free(self.@"#sequences");
}

pub fn loadFromOrder(self: *Execution, order: *Order) !void {
        _ = bun.assert((self.groups.len == 0));
        _ = bun.assert((self.@"#sequences".len == 0));
        var alloc_safety = bun.safety.CheckedAllocator.init(self.bunTest().gpa);
        _ = &alloc_safety;
        _ = alloc_safety.assertEq(order.groups.allocator);
        _ = alloc_safety.assertEq(order.sequences.allocator);
        self.groups = try order.groups.toOwnedSlice();
        self.@"#sequences" = try order.sequences.toOwnedSlice();
}

pub fn bunTest(self: *Execution) *BunTest {
        return @fieldParentPtr("execution", self);
}

pub fn handleTimeout(self: *Execution, globalThis: *jsc.JSGlobalObject) !void {
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        if (self.activeGroup()) |current_group| {
            _ = &current_group;
            const sequences = current_group.sequences(self);
            if ((sequences.len == 1)) {
                const sequence = sequences[0];
                if (sequence.active_entry) |entry| {
                    _ = &entry;
                    const now = bun.timespec.now(.force_real_time);
                    if ((entry.timespec.order((&now)) == .lt)) {
                        const kill_count = globalThis.bunVM().auto_killer.kill();
                        if ((kill_count.processes > 0)) {
                            _ = bun.Output.prettyErrorln("<d>killed {d} dangling process{s}<r>", .{ kill_count.processes, (if ((kill_count.processes != 1)) "es" else "") });
                            _ = bun.Output.flush();
                        }
                    }
                }
            }
        }
        _ = self.bunTest().addResult(.start);
}

pub fn activeGroup(self: *Execution) ?*ConcurrentGroup {
        if ((self.group_index >= self.groups.len)) {
            return null;
        }
        return (&self.groups[@as(usize, @intCast(self.group_index))]);
}

pub fn getCurrentAndValidExecutionSequence(self: *Execution, data: bun_test.BunTest.RefDataValue) ?CurrentExecutionSequenceAndGroup {
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        _ = groupLog.log("runOneCompleted: data: {f}", .{ data });
        if ((data != .execution)) {
            _ = groupLog.log("runOneCompleted: the data is not execution", .{});
            return null;
        }
        if ((data.execution.entry_data == null)) {
            _ = groupLog.log("runOneCompleted: the data did not know which entry was active in the group", .{});
            return null;
        }
        var data_mut = data;
        _ = &data_mut;
        if ((self.activeGroup() != data_mut.group(self.bunTest()))) {
            _ = groupLog.log("runOneCompleted: the data is for a different group", .{});
            return null;
        }
        const group = ((data_mut.group(self.bunTest())) orelse {
        _ = groupLog.log("runOneCompleted: the data did not know the group", .{});
        return null;
});
        const sequence = ((data_mut.sequence(self.bunTest())) orelse {
        _ = groupLog.log("runOneCompleted: the data did not know the sequence", .{});
        return null;
});
        if ((sequence.remaining_repeat_count != data.execution.entry_data.?.remaining_repeat_count)) {
            _ = groupLog.log("runOneCompleted: the data is for a previous repeat count (outdated)", .{});
            return null;
        }
        if (((blk: {
        break :blk @as(?*anyopaque, @ptrCast(sequence.active_entry));

}) != data.execution.entry_data.?.entry)) {
            _ = groupLog.log("runOneCompleted: the data is for a different sequence index (outdated)", .{});
            return null;
        }
        _ = groupLog.log("runOneCompleted: the data is valid and current", .{});
        return CurrentExecutionSequenceAndGroup{ .sequence = sequence, .group = group };
}

pub fn advanceSequence(self: *Execution, sequence: *ExecutionSequence, group: *ConcurrentGroup) void {
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        _ = bun.assert(sequence.executing);
        if (sequence.active_entry) |entry| {
            _ = &entry;
            _ = self.onEntryCompleted(entry);
            sequence.executing = false;
            if (sequence.maybe_skip) {
                sequence.maybe_skip = false;
                var skip_next: ?*ExecutionEntry = null;
                _ = &skip_next;
                if (entry.failure_skip_past) |failure_skip_past| {
                    _ = &failure_skip_past;
                    skip_next = failure_skip_past.next;
                }
                sequence.active_entry = skip_next;
            } else {
                sequence.active_entry = entry.next;
            }
        } else {
            if (bun.Environment.ci_assert) {
                _ = bun.assert(false);
            }
        }
        if ((sequence.active_entry == null)) {
            const test_failed = sequence.result.isFail();
            const test_passed = sequence.result.isPass(.pending_is_pass);
            if ((test_failed and (sequence.remaining_retry_count > 0))) {
                if ((sequence.flaky_attempt_count < ExecutionSequence.MAX_FLAKY_ATTEMPTS)) {
                    const elapsed_ns: u64 = (if (sequence.started_at.eql((&.epoch))) 0 else sequence.started_at.sinceNow(.force_real_time));
                    sequence.flaky_attempts_buf[cp_cast_int(usize, sequence.flaky_attempt_count)] = ExecutionFlakyAttempt{ .result = sequence.result, .elapsed_ns = elapsed_ns };
                    sequence.flaky_attempt_count = (sequence.flaky_attempt_count + 1);
                }
                sequence.remaining_retry_count = (sequence.remaining_retry_count - 1);
                _ = self.resetSequence(sequence);
                return;
            }
            if ((test_passed and (sequence.remaining_repeat_count > 0))) {
                sequence.remaining_repeat_count = (sequence.remaining_repeat_count - 1);
                _ = self.resetSequence(sequence);
                return;
            }
            _ = self.onSequenceCompleted(sequence);
            if ((group.remaining_incomplete_entries == 0)) {
                _ = bun.debugAssert(false);
                return;
            }
            group.remaining_incomplete_entries = (group.remaining_incomplete_entries - 1);
        }
}

pub fn onGroupStarted(self: *Execution, _: *ConcurrentGroup, globalThis: *jsc.JSGlobalObject) void {
    _ = self;
        const vm = globalThis.bunVM();
        _ = vm.auto_killer.enable();
}

pub fn onGroupCompleted(self: *Execution, _: *ConcurrentGroup, globalThis: *jsc.JSGlobalObject) void {
    _ = self;
        const vm = globalThis.bunVM();
        _ = vm.auto_killer.disable();
}

pub fn onSequenceStarted(self: *Execution, sequence: *ExecutionSequence) void {
    _ = self;
        if (sequence.test_entry) |entry| {
            _ = &entry;
            if ((entry.callback == null)) {
                return;
            }
        }
        sequence.started_at = bun.timespec.now(.force_real_time);
        if (sequence.test_entry) |entry| {
            _ = &entry;
            const entry_name = (((if (@typeInfo(@TypeOf(entry.base)) == .@"enum" or @typeInfo(@TypeOf(entry.base)) == .@"union") @tagName(entry.base) else entry.base.name)) orelse ("(unnamed)"));
            _ = log("Running test: \"{f}\"", .{ std.zig.fmtString(entry_name) });
            if ((entry.base.test_id_for_debugger != 0)) {
                var vm = jsc.VirtualMachine.get();
                _ = &vm;
                if (vm.debugger) |*debugger| {
                    _ = &debugger;
                    if ((debugger.*).test_reporter_agent.isEnabled()) {
                        _ = (debugger.*).test_reporter_agent.reportTestStart(entry.base.test_id_for_debugger);
                    }
                }
            }
        }
}

pub fn onEntryStarted(self: *Execution, entry: *ExecutionEntry) void {
    _ = self;
        if ((entry.callback == null)) {
            return;
        }
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        if ((entry.timeout != 0)) {
            _ = groupLog.log("-> entry.timeout: {}", .{ entry.timeout });
            entry.timespec = bun.timespec.msFromNow(.force_real_time, entry.timeout);
        } else {
            _ = groupLog.log("-> entry.timeout: 0", .{});
            entry.timespec = .epoch;
        }
}

pub fn onEntryCompleted(self: *Execution, _: *ExecutionEntry) void {
    _ = self;
}

pub fn onSequenceCompleted(self: *Execution, sequence: *ExecutionSequence) void {
        const elapsed_ns: u64 = (if (sequence.started_at.eql((&.epoch))) 0 else sequence.started_at.sinceNow(.force_real_time));
        switch (sequence.expect_assertions) {
.not_set => {

},
.at_least_one => {
if (((sequence.expect_call_count == 0) and sequence.result.isPass(.pending_is_pass))) {
            sequence.result = .fail_because_expected_has_assertions;
        }
},
.exact => |expected| {
if (((sequence.expect_call_count != expected) and sequence.result.isPass(.pending_is_pass))) {
            sequence.result = .fail_because_expected_assertion_count;
        }
},
}
        if ((sequence.result == .pending)) {
            sequence.result = (switch (sequence.entryMode()) {
.failing => .fail_because_failing_test_passed,
.todo => .fail_because_todo_passed,
else => .pass,
});
        }
        if (sequence.first_entry) |first_entry| {
            _ = &first_entry;
            if (((sequence.test_entry != null) or (sequence.result != .pass))) {
                const target_entry = ((sequence.test_entry) orelse (first_entry));
                _ = test_command.CommandLineReporter.handleTestCompleted(self.bunTest(), sequence, target_entry, elapsed_ns);
            }
        }
        if (sequence.test_entry) |entry| {
            _ = &entry;
            if ((entry.base.test_id_for_debugger != 0)) {
                var vm = jsc.VirtualMachine.get();
                _ = &vm;
                if (vm.debugger) |*debugger| {
                    _ = &debugger;
                    if ((debugger.*).test_reporter_agent.isEnabled()) {
                        const test_end_status = (switch (sequence.result) {
.pass => .pass,
.fail => .fail,
.skip => .skip,
.fail_because_timeout => .timeout,
.fail_because_timeout_with_done_callback => .timeout,
.fail_because_hook_timeout => .timeout,
.fail_because_hook_timeout_with_done_callback => .timeout,
.todo => .todo,
.skipped_because_label => .skipped_because_label,
.fail_because_failing_test_passed => .fail,
.fail_because_todo_passed => .fail,
.fail_because_expected_has_assertions => .fail,
.fail_because_expected_assertion_count => .fail,
.pending => .timeout,
});
                        _ = (debugger.*).test_reporter_agent.reportTestEnd(entry.base.test_id_for_debugger, test_end_status, @as(f64, @floatFromInt(elapsed_ns)));
                    }
                }
            }
        }
}

pub fn resetSequence(self: *Execution, sequence: *ExecutionSequence) void {
        _ = bun.assert((!sequence.executing));
        {
            var current_entry = sequence.first_entry;
            _ = &current_entry;
            while (current_entry) |entry| : (current_entry = entry.next) {
                while (((entry.next != null) and (entry.next.?.added_in_phase == .execution))) {
                    entry.next = entry.next.?.next;
                }
                entry.timespec = .epoch;
            }
        }
        const saved_flaky_attempt_count = sequence.flaky_attempt_count;
        const saved_flaky_attempts_buf = sequence.flaky_attempts_buf;
        sequence.* = ExecutionSequence.init(InitExecutionSequenceConfig{ .first_entry = sequence.first_entry, .test_entry = sequence.test_entry, .retry_count = sequence.remaining_retry_count, .repeat_count = sequence.remaining_repeat_count });
        sequence.flaky_attempt_count = saved_flaky_attempt_count;
        sequence.flaky_attempts_buf = saved_flaky_attempts_buf;
        if (jsc.Jest.Jest.runner) |runner| {
            _ = &runner;
            _ = runner.snapshots.resetCounts();
        }
        _ = self.group_index;
}

pub fn handleUncaughtException(self: *Execution, user_data: bun_test.BunTest.RefDataValue) bun_test.HandleUncaughtExceptionResult {
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        const cur_opt = self.getCurrentAndValidExecutionSequence(user_data);
        if ((cur_opt == null)) {
            return .show_unhandled_error_between_tests;
        }
        const cur = cur_opt.?;
        const sequence = cur.sequence;
        const group = cur.group;
        _ = &group;
        sequence.maybe_skip = true;
        if ((sequence.active_entry != sequence.test_entry)) {
            if ((sequence.result == .pending)) {
                sequence.result = .fail;
            }
            return .show_handled_error;
        }
        return (switch (sequence.entryMode()) {
.failing => {
{
            if ((sequence.result == .pending)) {
                sequence.result = .pass;
            }
            return .hide_error;
        }
},
.todo => {
{
            if ((sequence.result == .pending)) {
                sequence.result = .todo;
            }
            return .show_handled_error;
        }
},
else => {
{
            if ((sequence.result == .pending)) {
                sequence.result = .fail;
            }
            return .show_handled_error;
        }
},
});
}
const jsc = bun.jsc;
const bun_test = jsc.Jest.bun_test;
const BunTest = bun_test.BunTest;
const ExecutionEntry = bun_test.ExecutionEntry;
const Order = bun_test.Order;
const groupLog = bun_test.debug.group;
const log = bun.Output.scoped(.jest, .visible);
pub const EXECUTION_MAX_FLAKY_ATTEMPTS: usize = 16;

pub fn init(_: std.mem.Allocator) Execution {
        return Execution{ .groups = &.{}, .@"#sequences" = &.{}, .group_index = 0 };
}

pub fn step(buntest_strong: bun_test.BunTestPtr, globalThis: *jsc.JSGlobalObject, data: bun_test.BunTest.RefDataValue) !bun_test.StepResult {
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        var buntest: *BunTest = buntest_strong.get();
        _ = &buntest;
        var exec = (&buntest.execution);
        _ = &exec;
        var now = bun.timespec.now(.force_real_time);
        _ = &now;
        switch (data) {
.start => {
return try stepGroup(buntest_strong, globalThis, (&now));
},
else => {
const cur_opt = exec.getCurrentAndValidExecutionSequence(data);
        if ((cur_opt == null)) {
            _ = groupLog.log("runOneCompleted: the data is outdated, invalid, or did not know the sequence", .{});
            return bun_test.StepResult{ .waiting = .{} };
        }
        const cur = cur_opt.?;
        const sequence = cur.sequence;
        const group = cur.group;
        const sequence_index = data.execution.entry_data.?.sequence_index;
        if (bun.Environment.ci_assert) {
            _ = bun.assert((sequence.active_entry != null));
        }
        _ = exec.advanceSequence(sequence, group);
        const sequence_result = try stepSequence(buntest_strong, globalThis, group, sequence_index, (&now));
        switch (sequence_result) {
.done => {

},
.execute => |exec_st| {
return bun_test.StepResult{ .waiting = .{ .timeout = exec_st.timeout } };
},
}
        while ((group.next_sequence_index < group.sequences(exec).len)) : (group.next_sequence_index = (group.next_sequence_index + 1)) {
            const target_sequence = (&group.sequences(exec)[@as(usize, @intCast(group.next_sequence_index))]);
            if (target_sequence.executing) {
                continue;
            }
            const sequence_status = try stepSequence(buntest_strong, globalThis, group, group.next_sequence_index, (&now));
            switch (sequence_status) {
.done => {
_ = continue;
},
.execute => |exec_st| {
return bun_test.StepResult{ .waiting = .{ .timeout = exec_st.timeout } };
},
}
        }
        if ((group.remaining_incomplete_entries == 0)) {
            return try stepGroup(buntest_strong, globalThis, (&now));
        }
        return bun_test.StepResult{ .waiting = .{} };
},
}
}

pub fn stepGroup(buntest_strong: bun_test.BunTestPtr, globalThis: *jsc.JSGlobalObject, now: *bun.timespec) !bun_test.StepResult {
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        var buntest: *BunTest = buntest_strong.get();
        _ = &buntest;
        var exec = (&buntest.execution);
        _ = &exec;
        while (true) {
            const group_opt = exec.activeGroup();
            if ((group_opt == null)) {
                return .complete;
            }
            const group = group_opt.?;
            if ((!group.executing)) {
                _ = exec.onGroupStarted(group, globalThis);
                group.executing = true;
            }
            const status = try stepGroupOne(buntest_strong, globalThis, group, now);
            switch (status) {
.execute => |exec_st| {
return bun_test.StepResult{ .waiting = .{ .timeout = exec_st.timeout } };
},
.done => {

},
}
            group.executing = false;
            _ = exec.onGroupCompleted(group, globalThis);
            var all_failed = true;
            _ = &all_failed;
            for (cp_mut_slice(&group.sequences(exec))) |*sequence| {
                _ = &sequence;
                if ((!(sequence.*).result.isFail())) {
                    all_failed = false;
                    break;
                }
            }
            if (all_failed) {
                _ = groupLog.log("stepGroup: all sequences failed, skipping to failure_skip_to group", .{});
                exec.group_index = group.failure_skip_to;
            } else {
                _ = groupLog.log("stepGroup: not all sequences failed, advancing to next group", .{});
                exec.group_index = (exec.group_index + 1);
            }
        }
}

pub fn stepGroupOne(buntest_strong: bun_test.BunTestPtr, globalThis: *jsc.JSGlobalObject, group: *ConcurrentGroup, now: *bun.timespec) !*AdvanceStatus {
        var buntest: *BunTest = buntest_strong.get();
        _ = &buntest;
        var exec = (&buntest.execution);
        _ = &exec;
        var final_status: *AdvanceStatus = .done;
        _ = &final_status;
        var concurrent_limit: usize = 20;
        _ = &concurrent_limit;
        if (buntest.reporter) |reporter| {
            _ = &reporter;
            concurrent_limit = reporter.jest.max_concurrency;
        } else {
            _ = bun.assert(false);
        }
        var active_count: usize = 0;
        _ = &active_count;
        var sequence_index: usize = 0;
        _ = &sequence_index;
        while ((sequence_index < group.sequences(exec).len)) : (sequence_index = (sequence_index + 1)) {
            const sequence_status = try stepSequence(buntest_strong, globalThis, group, sequence_index, now);
            switch (sequence_status) {
.done => {

},
.execute => |exec_st| {
var prev_timeout: bun.timespec = .epoch;
            _ = &prev_timeout;
            if ((final_status == .execute)) {
                prev_timeout = final_status.execute.timeout;
            }
            const this_timeout = exec_st.timeout;
            final_status = AdvanceStatus{ .execute = ExecuteStatus{ .timeout = prev_timeout.minIgnoreEpoch(this_timeout) } };
            active_count = (active_count + 1);
            if (((concurrent_limit != 0) and (active_count >= concurrent_limit))) {
                break;
            }
},
}
        }
        return final_status;
}

pub fn stepSequence(buntest_strong: bun_test.BunTestPtr, globalThis: *jsc.JSGlobalObject, group: *ConcurrentGroup, sequence_index: usize, now: *bun.timespec) !*AdvanceSequenceStatus {
        while (true) {
            if (try stepSequenceOne(buntest_strong, globalThis, group, sequence_index, now)) |res| {
                _ = &res;
                return res;
            }
        }
}

pub fn stepSequenceOne(buntest_strong: bun_test.BunTestPtr, globalThis: *jsc.JSGlobalObject, group: *ConcurrentGroup, sequence_index: usize, now: *bun.timespec) !?*AdvanceSequenceStatus {
        _ = groupLog.begin(@src());
        defer {
        _ = groupLog.end();
        }
        var buntest: *BunTest = buntest_strong.get();
        _ = &buntest;
        var exec = (&buntest.execution);
        _ = &exec;
        const sequence = (&group.sequences(exec)[@as(usize, @intCast(sequence_index))]);
        if (sequence.executing) {
            const active_entry_opt = sequence.active_entry;
            if ((active_entry_opt == null)) {
                _ = bun.debugAssert(false);
                return AdvanceSequenceStatus{ .execute = ExecuteStatus{  } };
            }
            const active_entry = active_entry_opt.?;
            if (active_entry.evaluateTimeout(sequence, now)) {
                _ = exec.advanceSequence(sequence, group);
                return null;
            }
            _ = groupLog.log("runOne: cannot advance; already executing", .{});
            return AdvanceSequenceStatus{ .execute = ExecuteStatus{ .timeout = active_entry.timespec } };
        }
        const next_item_opt = sequence.active_entry;
        if ((next_item_opt == null)) {
            _ = groupLog.log("runOne: no more entries; sequence complete.", .{});
            return .done;
        }
        const next_item = next_item_opt.?;
        sequence.executing = true;
        if ((next_item == sequence.first_entry)) {
            _ = exec.onSequenceStarted(sequence);
        }
        _ = exec.onEntryStarted(next_item);
        if (next_item.callback) |cb| {
            _ = &cb;
            _ = groupLog.log("runSequence queued callback", .{});
            const callback_data: bun_test.BunTest.RefDataValue = .{ .execution = .{ .group_index = exec.group_index, .entry_data = .{ .sequence_index = sequence_index, .entry = next_item, .remaining_repeat_count = sequence.remaining_repeat_count } } };
            _ = groupLog.log("runSequence queued callback: {f}", .{ callback_data });
            if ((BunTest.runTestCallback(buntest_strong, globalThis, cb.get(), next_item.has_done_parameter, callback_data, (&next_item.timespec)) != null)) {
                now.* = bun.timespec.now(.force_real_time);
                _ = next_item.evaluateTimeout(sequence, now);
                _ = exec.advanceSequence(sequence, group);
                return null;
            }
            return AdvanceSequenceStatus{ .execute = ExecuteStatus{ .timeout = next_item.timespec } };
        } else {
            switch (next_item.base.mode) {
.skip => {
if ((sequence.result == .pending)) {
                sequence.result = .skip;
            }
},
.todo => {
if ((sequence.result == .pending)) {
                sequence.result = .todo;
            }
},
.filtered_out => {
if ((sequence.result == .pending)) {
                sequence.result = .skipped_because_label;
            }
},
else => {
_ = groupLog.log("runSequence: no callback for sequence_index {d} (entry_index {x})", .{ sequence_index, @intFromPtr(sequence.active_entry) });
            _ = bun.debugAssert(false);
},
}
            _ = exec.advanceSequence(sequence, group);
            return null;
        }
}
